-- ============================================================
-- App Runtime 版: デモデータ（KMOT_AWS1 スナップショット）の投入
-- 前提: リポジトリ直下の setup.sql を実行済み（LIFEINSURANCE_DEMO_DB / LIFEINSURANCE_DEMO_WH が存在）
-- 実行: リポジトリ直下で  snow sql -c <接続名> -f <このファイル>
-- ============================================================
USE ROLE ACCOUNTADMIN;
USE WAREHOUSE LIFEINSURANCE_DEMO_WH;
USE DATABASE LIFEINSURANCE_DEMO_DB;

-- PUT はローカルファイルを使うため snow CLI（CoCo Desktop / ターミナル）で実行すること。
-- Snowsight ワークシートでは PUT は動かない。
CREATE FILE FORMAT IF NOT EXISTS PUBLIC.FF_SNAPSHOT_JSON TYPE = JSON COMPRESSION = GZIP;
CREATE STAGE IF NOT EXISTS PUBLIC.APP_SNAPSHOT_STAGE FILE_FORMAT = PUBLIC.FF_SNAPSHOT_JSON;
PUT file://app-runtime/snapshot/data/*.json.gz @PUBLIC.APP_SNAPSHOT_STAGE AUTO_COMPRESS = FALSE OVERWRITE = TRUE;

COPY INTO LIFEINSURANCE_DEMO_DB.RAW.T_COMPANY_NEWS FROM @PUBLIC.APP_SNAPSHOT_STAGE/T_COMPANY_NEWS.json.gz FILE_FORMAT = (FORMAT_NAME = PUBLIC.FF_SNAPSHOT_JSON) MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE FORCE = TRUE;
COPY INTO LIFEINSURANCE_DEMO_DB.RAW.T_CONTACT_TOUCHPOINTS FROM @PUBLIC.APP_SNAPSHOT_STAGE/T_CONTACT_TOUCHPOINTS.json.gz FILE_FORMAT = (FORMAT_NAME = PUBLIC.FF_SNAPSHOT_JSON) MATCH_BY_COLUMN_NAME = CASE_INSENSITIVE FORCE = TRUE;
